package com.travbook;
import com.travbook.journeys.domain.model.Journey.*;
import com.travbook.shared.domain.*;
import com.travbook.operations.application.port.in.Operations;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import java.util.*;
import java.time.*;
import java.net.*;
import java.net.http.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;
/** Inherits lifecycle checks against the same isolated PostgreSQL/issuer fixtures. */
class JourneyReviewIntegrationTest extends JourneyIntegrationTest {
 @Autowired Operations operations;@Autowired com.travbook.journeys.application.port.out.JourneySupplier supplier;
 String operator()throws Exception{return issuer.token("journey-operator","",Map.of("travbook_roles",List.of("operations_reconcile"),"amr",List.of("mfa"),"auth_time",Instant.now().getEpochSecond()));}
 Booking reviewed(Kind kind,boolean receipt){var r=switch(kind){case BUS->bus();case CAB->cab();case HOLIDAY->holiday(false);};var b=book(r,Scenario.NORMAL);if(kind==Kind.BUS)b=advance(b,Status.AWAITING_PAYMENT);journeys.pay(identity,b.id(),key(),correlation());for(int n=0;n<50&&journeys.booking(identity,b.id()).step()!=Step.RESERVE;n++){worker.tick();clock.now=clock.now.plusMillis(100);}var claim=store.claim().orElseThrow();assertThat(claim.booking().id()).isEqualTo(b.id());if(receipt)assertThat(effects.execute(claim.booking(),Step.RESERVE).accepted()).isTrue();assertThat(store.complete(claim,claim.booking().review(clock.instant()))).isTrue();return journeys.booking(identity,b.id());}
 HttpResponse<String> post(String path,String auth,String key,Object body)throws Exception{return HttpClient.newHttpClient().send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+path)).header("Authorization","Bearer "+auth).header("Idempotency-Key",key).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))).build(),HttpResponse.BodyHandlers.ofString());}
 @Test void allKindsResumeOnlyWithVerifiedEvidenceAndImmutableAudit()throws Exception{for(var kind:Kind.values()){day++;var b=reviewed(kind,true);String path="/api/v2/operations/reviews/"+kind+"/"+b.id(),op=operator(),k=key();var body=Map.of("version",b.version(),"reason","PROVIDER_STATUS_AVAILABLE","consent",true);assertThat(call(path,token).statusCode()).isEqualTo(403);assertThat(post(path+"/resume",token,k,body).statusCode()).isEqualTo(403);var details=call(path,op);assertThat(details.statusCode()).isEqualTo(200);assertThat(details.body()).doesNotContain("Sample Person","sample@example.test",identity.subject());var response=post(path+"/resume",op,k,body);assertThat(response.statusCode()).as(response.body()).isEqualTo(202);assertThat(post(path+"/resume",op,k,body).body()).isEqualTo(response.body());assertThat(advance(b,Status.CONFIRMED).payment()).isEqualTo(Payment.CAPTURED);assertThat(jdbc.sql("select count(*) from payment_journal where payment_id=:id").param("id",b.id()).query(Integer.class).single()).isEqualTo(2);assertThat(jdbc.sql("select count(*) from journey_supplier_receipt where booking_id=:id and step='RESERVE'").param("id",b.id()).query(Integer.class).single()).isEqualTo(1);assertThatThrownBy(()->jdbc.sql("delete from journey_recovery_action where booking_id=:id").param("id",b.id()).update()).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(post(path+"/resume",op,k,Map.of("version",b.version(),"reason","RETRY_AFTER_OUTAGE","consent",true)).statusCode()).isEqualTo(409);}}
 @Test void absentReceiptWrongKindAndStaleMfaRemainBlocked()throws Exception{var b=reviewed(Kind.CAB,false);var body=Map.of("version",b.version(),"reason","RETRY_AFTER_OUTAGE","consent",true);String base="/api/v2/operations/reviews/";assertThat(call("/api/v1/operations/reviews/CAB/"+b.id(),operator()).statusCode()).isEqualTo(422);assertThat(post(base+"CAB/"+b.id()+"/resume",operator(),key(),body).statusCode()).isEqualTo(409);assertThat(call(base+"BUS/"+b.id(),operator()).statusCode()).isEqualTo(404);for(var claims:List.of(Map.<String,Object>of("travbook_roles",List.of("operations_reconcile")),Map.<String,Object>of("travbook_roles",List.of("operations_reconcile"),"amr",List.of("mfa"),"auth_time",Instant.now().minusSeconds(601).getEpochSecond()))){assertThat(call(base+"CAB",issuer.token("bad-operator","",claims)).statusCode()).isEqualTo(403);}assertThat(journeys.booking(identity,b.id()).status()).isEqualTo(Status.REVIEW);assertThat(jdbc.sql("select count(*) from journey_recovery_action where booking_id=:id").param("id",b.id()).query(Integer.class).single()).isZero();}
 @Test void historicalReservationReceiptCannotOverrideCurrentCancellation()throws Exception{var b=reviewed(Kind.CAB,true);supplier.execute(b,Step.CANCEL);assertThat(post("/api/v2/operations/reviews/CAB/"+b.id()+"/resume",operator(),key(),Map.of("version",b.version(),"reason","PROVIDER_STATUS_AVAILABLE","consent",true)).statusCode()).isEqualTo(409);assertThat(journeys.booking(identity,b.id()).status()).isEqualTo(Status.REVIEW);}
 boolean resume(Booking b,String actor){try{operations.resume(Recovery.Kind.CAB,b.id(),b.version(),actor,Recovery.Reason.PROVIDER_STATUS_AVAILABLE,true,key(),correlation());return true;}catch(DomainFailure e){assertThat(e.code()).isEqualTo(DomainFailure.Code.BOOKING_CONFLICT);return false;}}
 @Test void concurrentOperatorsResumeOneVersionOnly()throws Exception{var b=reviewed(Kind.CAB,true);try(var pool=Executors.newFixedThreadPool(2)){var results=pool.invokeAll(List.<Callable<Boolean>>of(()->resume(b,"a".repeat(64)),()->resume(b,"b".repeat(64))));assertThat(results.stream().filter(f->{try{return f.get();}catch(Exception e){throw new RuntimeException(e);}}).count()).isEqualTo(1);}assertThat(advance(b,Status.CONFIRMED).reservation()).isEqualTo(Reservation.CONFIRMED);}
 @Test void outboxFailureRollsBackRecoveryAndBudgetIsBounded(){var b=reviewed(Kind.CAB,true);jdbc.sql("create function reject_journey_recovery() returns trigger language plpgsql as $$ begin raise exception 'Injected'; end $$").update();jdbc.sql("create trigger reject_journey_recovery before insert on journey_outbox for each row execute function reject_journey_recovery()").update();try{var current=b;assertThatThrownBy(()->resume(current,"a".repeat(64))).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(journeys.booking(identity,b.id()).version()).isEqualTo(b.version());}finally{jdbc.sql("drop trigger reject_journey_recovery on journey_outbox").update();jdbc.sql("drop function reject_journey_recovery()").update();}for(int n=0;n<3;n++){assertThat(resume(b,"a".repeat(64))).isTrue();var c=store.claim().orElseThrow();store.complete(c,c.booking().review(clock.instant()));b=journeys.booking(identity,b.id());}assertThat(resume(b,"a".repeat(64))).isFalse();assertThat(store.review(Kind.CAB,b.id()).actions()).hasSize(3);}
 @Test void oldReviewsWithoutCheckpointAreNotInferred()throws Exception{var b=reviewed(Kind.CAB,true);jdbc.sql("alter table journey_review_checkpoint disable trigger immutable_journey_checkpoint").update();try{jdbc.sql("delete from journey_review_checkpoint where booking_id=:id").param("id",b.id()).update();}finally{jdbc.sql("alter table journey_review_checkpoint enable trigger immutable_journey_checkpoint").update();}assertThat(store.review(Kind.CAB,b.id()).recoverable()).isFalse();assertThat(resume(b,"a".repeat(64))).isFalse();assertThat(post("/api/v2/operations/reviews/CAB/"+b.id()+"/reconcile-legacy",operator(),key(),Map.of("version",b.version(),"reason","PROVIDER_STATUS_AVAILABLE","consent",true)).statusCode()).isEqualTo(404);}
}
